  `salary_month` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Format: YYYY-MM',
  `payment_method` enum('cash','card','bank_transfer') COLLATE utf8mb4_unicode_ci DEFAULT 'bank_transfer',
  `transaction_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bonus` decimal(10,2) DEFAULT '0.00',
  `deductions` decimal(10,2) DEFAULT '0.00',
  `net_amount` decimal(10,2) GENERATED ALWAYS AS (((`amount` + `bonus`) - `deductions`)) STORED,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `paid_by` int DEFAULT NULL,
  `paid_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
